-- 観光地(spot_type='tourist')の初期データ 全3,190件
-- (旧 02_seed.sql 51件 + 04_more_spots.sql 105件 + 09_bulk_spots.sql 2,585件を統合、
--  +全国47都道府県231件を国土数値情報(観光資源)との名寄せで発見し追加。座標・説明文はWikipedia/OSM由来で
--  国土数値情報の内容そのものは一切転記していない。既存データと重複するもの・河川や動植物など
--  地図ピンとして不適切なものはリードから除外している。
--  +御朱印スポット(spot_type='goshuin')でSランクの寺社のうち未登録だった219件(172件+重複判定
--  修正後の47件)を追加。この219件のランクは当初御朱印側のSを流用していたが、母集団の異なる
--  基準のため観光地基準で振り直し済み(ファイル末尾の該当ブロックのコメント参照))
-- 座標はおおよその値(bulk分はOSMジオコーディング、カテゴリもOSMタグからの機械的導出)。
-- ランクはWikipedia(ja)月次ページビュー数のパーセンタイル区分による(lib/types.tsのコメント参照)。
-- 追加分231件のランクは直近60日ページビューと既存スポットとの相対比較+世界遺産指定の目視格上げによる簡易判定。
insert into spots
  (spot_type_id, name, name_kana, prefecture, municipality, lat, lng, rank, category, description)
