    ('二条城', 'にじょうじょう', '京都府', '京都市', 35.0141556, 135.7475, 'S', '城', '徳川家康が築いた平城で、大政奉還の舞台となった世界遺産。'),
    ('京都御所', 'きょうとごしょ', '京都府', '京都市', 35.0252778, 135.7622222, 'S', 'その他', '明治まで天皇の住まいであった京都のシンボル的皇室施設。'),
    ('南禅寺', 'なんぜんじ', '京都府', '京都市', 35.0119833, 135.7943889, 'S', '神社仏閣', '水路閣(レンガ造アーチ橋)で知られる臨済宗大本山の禅寺。'),
