    ('苔寺(西芳寺)', 'こけでら', '京都府', '京都市', 34.9919611, 135.6833139, 'S', '神社仏閣', '一面の苔庭で知られる世界遺産の枯山水・池泉回遊式庭園。'),
    ('醍醐寺', 'だいごじ', '京都府', '京都市', 34.9515, 135.8217778, 'S', '神社仏閣', '豊臣秀吉の「醍醐の花見」で知られる世界遺産の古刹。'),
    ('祇園', 'ぎおん', '京都府', '京都市', 35.0046897, 135.778403, 'S', '街並み', '花見小路や舞妓で知られる京都を代表する花街・繁華街。'),
