    -- 御朱印スポットでSランク(直近60日ページビュー上位5%)に登録されている寺社のうち、
    -- 観光地スポットに未登録のもの172件を追加(既存2,971件と名前・300m近接で重複チェック済み)。
    -- 座標・説明文は御朱印スポット側のデータ(Wikipedia/OSM由来)をそのまま流用。
    --
    -- ランクについて(この172件と後続の47件に共通): 御朱印のSは「寺社約6,600件中の上位5%」で
    -- 観光地とは母集団が異なるため、観光地基準で振り直している。具体的には、
    -- 03_goshuin_spots.sqlのSブロック内の並び(=ページビュー降順)を順位として使い、
    -- 御朱印Sのうち観光地マップに元から存在した約90件の観光地ランクとの対応で境界を較正した
    -- (御朱印S内のおおよそ上位60位まで→S、それ以下→A。既存側でも御朱印S帯の寺社は
    -- B以下がごく稀でほぼS/Aに収まっており、この2区分で整合する)。
    -- さらに目視で調整: 世界遺産の上賀茂神社・二荒山神社(日光)はAからSへ格上げ。
    -- Wikipedia記事とスポットの実体が乖離しページビューが過大なもの(崇徳天皇御廟=記事は
    -- 天皇本人、立正佼成会=記事は教団全体で実体は苫小牧の施設、生國魂神社行宮=記事は本社、
    -- 東峰神社・修多羅寺・円光寺・成願寺・吉祥寺・阿遅速遅神社・櫻田山神社、
    -- および一時的スパイクとみられる等持院)はA〜Dへ格下げ。
    ('猿田彦神社', null, '三重県', null, 34.4673487, 136.720861, 'A', '神社仏閣', '猿田彦神社（さるたひこじんじゃ）は、三重県伊勢市の伊勢神宮内宮の近くにある神社である。猿田彦大神と、その子孫の大田命を祭神とする。'),
    ('三室戸寺', null, '京都府', null, 34.8997569, 135.8183283, 'A', '神社仏閣', '三室戸寺（みむろとじ）は、京都府宇治市にある本山修験宗の別格本山の寺院。山号は明星山。'),
    ('上御霊神社', null, '京都府', null, 35.0365172, 135.7614034, 'A', '神社仏閣', '上御霊神社（かみごりょうじんじゃ）は、京都市上京区上御霊竪町にある神社。旧社格は府社。'),
