    ('平野神社', null, '京都府', null, 35.032364, 135.7325114, 'A', '神社仏閣', '平野神社（ひらのじんじゃ）は、京都市北区平野宮本町にある神社。式内社（名神大社）で、二十二社（上七社）の一社。'),
