    ('月読神社', null, '京都府', null, 34.9965339, 135.6860518, 'A', '神社仏閣', '月読神社（つきよみじんじゃ、月讀神社）は、京都市西京区にある神社。式内社（名神大社）で、現在は松尾大社摂社。'),
