    ('相国寺', null, '京都府', null, 35.0325994, 135.761858, 'A', '神社仏閣', '相国寺（しょうこくじ）は、京都市上京区相国寺門前町にある臨済宗相国寺派の大本山の寺院。山号は萬年山（まんねんざん）。'),
