    ('圓教寺', null, '兵庫県', '姫路市', 34.8888373, 134.6576603, 'S', '神社仏閣', '圓教寺（円教寺、えんぎょうじ）は、兵庫県姫路市書写にある天台宗の別格本山の寺院。山号は書寫山（書写山）。'),
    ('太山寺', null, '兵庫県', null, 34.6966355, 135.0674475, 'A', '神社仏閣', '太山寺（たいさんじ）は、兵庫県神戸市西区にある天台宗の寺院。山号は三身山（さんしんざん）。'),
    ('神呪寺', null, '兵庫県', null, 34.7731861, 135.3298353, 'A', '神社仏閣', '神呪寺（かんのうじ、神咒寺）は、兵庫県西宮市甲山町にある真言宗御室派の別格本山の寺院。山号は甲山。'),
    ('中山寺', null, '兵庫県', null, 34.8212057, 135.3678039, 'A', '神社仏閣', '中山寺（なかやまでら）は、兵庫県宝塚市中山寺にある真言宗中山寺派の大本山の寺院。山号は紫雲山。'),
    ('須磨寺', null, '兵庫県', null, 34.6491725, 135.1114723, 'A', '神社仏閣', null),
    ('鶴林寺', null, '兵庫県', null, 34.7522463, 134.8328727, 'A', '神社仏閣', null),
    ('北海道神宮', null, '北海道', null, 43.0545817, 141.3092301, 'A', '神社仏閣', '北海道神宮（ほっかいどうじんぐう）は、北海道札幌市中央区にある神社（神宮）。円山公園に隣接する。'),
    ('立正佼成会', null, '北海道', '苫小牧市', 42.6532521, 141.629912, 'D', '神社仏閣', null),
    ('中山法華経寺', null, '千葉県', '市川市', 35.7202948, 139.9482157, 'A', '神社仏閣', '法華経寺（ほけきょうじ）は、千葉県市川市中山二丁目にある日蓮宗大本山の寺院である。鎌倉時代の文応元年（1260年）創立。'),
    ('千葉神社', null, '千葉県', '千葉市', 35.6117558, 140.1237789, 'A', '神社仏閣', '千葉神社（ちばじんじゃ）は、千葉県千葉市中央区にある神社。旧社格は県社。'),
    ('安房神社', null, '千葉県', '館山市', 34.922593, 139.8370142, 'A', '神社仏閣', '安房神社（あわじんじゃ）は、千葉県館山市大神宮にある神社。式内社（名神大社）、安房国一宮。'),
    ('東峰神社', null, '千葉県', null, 35.784907, 140.3932153, 'D', '神社仏閣', '東峰神社（とうほうじんじゃ）は、千葉県成田市東峰にある神社。'),
    ('洲崎神社', null, '千葉県', null, 34.9680853, 139.7576847, 'A', '神社仏閣', '洲崎神社（すさきじんじゃ/すのさきじんじゃ）は、千葉県館山市洲崎にある神社。式内社（大社）論社で、江戸時代に安房国一宮とされた。'),
    ('玉前神社', null, '千葉県', null, 35.3761992, 140.3605288, 'A', '神社仏閣', '玉前神社（たまさきじんじゃ）は、千葉県長生郡一宮町一宮にある神社。式内社（名神大社）、上総国一宮。'),
    ('麻賀多神社', null, '千葉県', null, 35.7707427, 140.2763125, 'A', '神社仏閣', null),
    ('丹生都比売神社', null, '和歌山県', 'かつらぎ町', 34.2630761, 135.5214845, 'A', '神社仏閣', '丹生都比売神社（にうつひめじんじゃ、にぶつひめじんじゃ、丹生都比賣神社）は、和歌山県伊都郡かつらぎ町上天野にある神社。式内社（名神大社）、紀伊国一宮。'),
    ('淡嶋神社', null, '和歌山県', null, 34.273696, 135.0666881, 'A', '神社仏閣', '淡嶋神社（あわしまじんじゃ）は、和歌山県和歌山市加太にある神社。式内社論社で、旧社格は郷社。'),
    ('喜多院', null, '埼玉県', null, 35.9178006, 139.488985, 'A', '神社仏閣', '喜多院（きたいん）は、埼玉県川越市にある天台宗の寺院。山号は星野山（せいやさん）。'),
    ('氷川女体神社', null, '埼玉県', null, 35.8869208, 139.6937649, 'A', '神社仏閣', '氷川女体神社（ひかわにょたいじんじゃ）は、埼玉県さいたま市緑区にある神社。登記上の宗教法人名称は旧字体の氷川女體神社である。'),
    ('調神社', null, '埼玉県', 'さいたま市', 35.8534177, 139.6556849, 'A', '神社仏閣', '調神社（つきじんじゃ）は、埼玉県さいたま市浦和区岸町三丁目にある神社。式内社で、旧社格は県社。'),
    ('高麗神社', null, '埼玉県', null, 35.8985741, 139.3227046, 'A', '神社仏閣', null),
    ('鷲宮神社', null, '埼玉県', '久喜市', 36.0999753, 139.6548687, 'A', '神社仏閣', null),
    ('英彦山神社', null, '大分県', null, 33.4779478, 130.9262449, 'A', '神社仏閣', null),
    ('サムハラ神社', null, '大阪府', null, 34.6789515, 135.4909725, 'A', '神社仏閣', 'サムハラ神社（サムハラじんじゃ）は、大阪府大阪市西区立売堀（いたちぼり）にある神社である。'),
    ('一心寺', null, '大阪府', null, 34.6527185, 135.5106576, 'A', '神社仏閣', '一心寺（いっしんじ）は、大阪市天王寺区にある浄土宗の寺院。山号は坂松山（ばんしょうざん）。'),
    ('叡福寺', null, '大阪府', '太子町', 34.5187985, 135.6391072, 'A', '神社仏閣', '叡福寺（えいふくじ）は、大阪府南河内郡太子町太子にある太子宗の本山の寺院。山号は磯長山（しながさん）。'),
    ('大阪天満宮', null, '大阪府', null, 34.6961478, 135.5127788, 'A', '神社仏閣', '大阪天満宮（おおさかてんまんぐう）は、大阪市北区天神橋にある神社。別名に天満天神・浪華菅廟・中島天満宮がある。'),
    ('大鳥大社', null, '大阪府', '大阪市', 34.5364001, 135.4604746, 'A', '神社仏閣', '大鳥大社（おおとりたいしゃ）は、大阪府堺市西区鳳北町にある神社。和泉国大鳥郡の式内社（名神大社）で、和泉国一宮。'),
    ('安居神社', null, '大阪府', null, 34.6544824, 135.5109293, 'A', '神社仏閣', '安居神社（やすいじんじゃ）は、大阪市天王寺区にある神社。旧社格は村社。'),
    ('杭全神社', null, '大阪府', null, 34.6286767, 135.5548792, 'A', '神社仏閣', '杭全神社（くまたじんじゃ）は大阪市平野区平野宮町にある神社。旧社格は府社。'),
    ('枚岡神社', null, '大阪府', null, 34.6698429, 135.6505061, 'A', '神社仏閣', '枚岡神社（ひらおかじんじゃ）は、大阪府東大阪市出雲井町（いずもいちょう）にある神社。式内社（名神大社）、河内国一宮。'),
    ('槇尾山施福寺（槇尾寺）', null, '大阪府', null, 34.3929129, 135.5116081, 'A', '神社仏閣', '施福寺（せふくじ）は、大阪府和泉市槙尾山町にある天台宗の寺院。山号は槇尾山。'),
    ('水無瀬神宮', null, '大阪府', null, 34.8850406, 135.6727538, 'A', '神社仏閣', '水無瀬神宮（みなせじんぐう）は、大阪府三島郡島本町にある神社。旧社格は官幣大社で、現在は神社本庁の別表神社。'),
    ('水間観音', null, '大阪府', null, 34.3988311, 135.3861089, 'A', '神社仏閣', '水間寺（みずまでら）は、大阪府貝塚市水間にある天台宗の別格本山の寺院。山号は龍谷山。'),
    ('生國魂神社行宮', null, '大阪府', null, 34.6823424, 135.5112403, 'D', '神社仏閣', null),
    ('葛井寺(藤井寺)', null, '大阪府', null, 34.5700444, 135.5965987, 'A', '神社仏閣', null),
    ('観心寺', null, '大阪府', '河内長野市', 34.4369378, 135.5985146, 'A', '神社仏閣', null),
    ('豊国神社', null, '大阪府', null, 34.6843094, 135.5264155, 'A', '神社仏閣', null),
    ('道明寺', null, '大阪府', null, 34.5688393, 135.6160097, 'A', '神社仏閣', null),
    ('阿遅速遅神社', null, '大阪府', null, 34.6887895, 135.5650147, 'C', '神社仏閣', null),
    ('露天神社', null, '大阪府', null, 34.6991011, 135.5008272, 'A', '神社仏閣', null),
    ('中宮寺', null, '奈良県', '斑鳩町', 34.6149294, 135.739858, 'A', '神社仏閣', '中宮寺（ちゅうぐうじ）は、奈良県生駒郡斑鳩町法隆寺北にある聖徳宗の寺院。山号は法興山。'),
    ('大峯山寺', null, '奈良県', null, 34.2534066, 135.9400235, 'A', '神社仏閣', '大峯山寺（おおみねさんじ）は、奈良県吉野郡天川村にある修験道の寺院である。大峯山山上ヶ岳の山頂に建つ。'),
    ('寶山寺', null, '奈良県', null, 34.6843892, 135.6864001, 'A', '神社仏閣', '寳山寺（ほうざんじ）は、奈良県生駒市門前町にある真言律宗の大本山の寺院。山号は生駒山。'),
    ('新薬師寺', null, '奈良県', null, 34.6758346, 135.8458855, 'A', '神社仏閣', '新薬師寺（しんやくしじ）は、奈良県奈良市高畑町にある華厳宗の寺院。山号は日輪山。'),
    ('朝護孫子寺', null, '奈良県', null, 34.6090885, 135.6703389, 'A', '神社仏閣', '朝護孫子寺（ちょうごそんしじ）は、奈良県生駒郡平群町信貴山にある信貴山真言宗の総本山の寺院。山号は信貴山。'),
    ('橿原神宮', null, '奈良県', null, 34.4878708, 135.7871787, 'S', '神社仏閣', '橿原神宮（かしはらじんぐう）は、奈良県橿原市久米町にある神社。旧社格は官幣大社、勅祭社。'),
    ('法華寺', null, '奈良県', '奈良市', 34.6921886, 135.8044572, 'A', '神社仏閣', '法華寺（ほっけじ）は、奈良県奈良市法華寺町にある光明宗の本山の寺院。山号はなし。'),
    ('法起寺', null, '奈良県', '斑鳩町', 34.6227775, 135.7460229, 'A', '神社仏閣', '法起寺（ほっきじ、ほうきじ）は、奈良県生駒郡斑鳩町岡本にある聖徳宗の寺院。山号は岡本山。'),
    ('當麻寺', null, '奈良県', null, 34.5159946, 135.6944964, 'A', '神社仏閣', '當麻寺（たいまでら、常用漢字体：当麻寺）は、奈良県葛城市當麻にある真言宗・浄土宗二宗の寺院。法号は禅林寺。'),
    ('荒神社', null, '奈良県', null, 34.1575318, 135.6563827, 'A', '神社仏閣', '立里荒神社（たてりこうじんしゃ）は、奈良県吉野郡野迫川村大字池津川にある神社である。空海が高野山を開創する際に祀ったと伝わる。'),
    ('金峯山寺', null, '奈良県', null, 34.3682805, 135.85798, 'S', '神社仏閣', null),
    ('櫻田山神社', null, '宮城県', '栗原市', 38.7958176, 140.9848698, 'B', '神社仏閣', '櫻田山神社（さくらださんじんじゃ）は、宮城県栗原市栗駒桜田にある神社。正式名称は山神社（さんじんじゃ）であるが、地区名の桜田を冠した「櫻田山神社」で一般に呼ばれる。'),
    ('鵜戸神宮', null, '宮崎県', '日南市', 31.6492649, 131.466212, 'A', '神社仏閣', null),
    ('雄山神社峰本社', null, '富山県', null, 36.5732195, 137.6178679, 'A', '神社仏閣', null),
    ('北口本宮冨士浅間神社', null, '山梨県', null, 35.4710185, 138.7926872, 'A', '神社仏閣', '北口本宮冨士浅間神社（きたぐちほんぐうふじせんげんじんじゃ）は、山梨県富士吉田市上吉田にある神社。旧社格は県社で、現在は神社本庁の別表神社。'),
    ('武田神社', null, '山梨県', '甲府市', 35.6866895, 138.5773898, 'A', '神社仏閣', '武田神社（たけだじんじゃ）は、山梨県甲府市古府中町にある神社。躑躅ヶ崎館の跡地（武田氏館跡）に建てられており、武田信玄を祭神とする。'),
    ('甲斐善光寺', null, '山梨県', null, 35.6659552, 138.5929174, 'A', '神社仏閣', '善光寺（ぜんこうじ）は、山梨県甲府市善光寺にある浄土宗の寺院。山号は定額山（じょうがくざん）。'),
    ('南宮大社', null, '岐阜県', null, 35.3606897, 136.5253565, 'A', '神社仏閣', '南宮大社（なんぐうたいしゃ）は、岐阜県不破郡垂井町にある神社。古くから「なんぐうさん」と呼ばれる。'),
    ('吉備津彦神社', null, '岡山県', null, 34.6765715, 133.8635129, 'A', '神社仏閣', '吉備津彦神社（きびつひこじんじゃ）は、岡山県岡山市北区一宮にある神社。備前国一宮。'),
    ('最上稲荷', null, '岡山県', '岡山市', 34.7099921, 133.8321428, 'A', '神社仏閣', '最上稲荷（さいじょういなり）は、岡山県岡山市北区にある日蓮宗の寺である。正式名称は最上稲荷山妙教寺。'),
    ('日御碕神社', null, '島根県', null, 35.4295631, 132.6297468, 'A', '神社仏閣', '日御碕神社（ひのみさきじんじゃ）は島根県出雲市の日御碕に鎮座する神社。通称、みさきさん。'),
    ('熊野大社', null, '島根県', null, 35.3732128, 133.0705728, 'A', '神社仏閣', '熊野大社（くまのたいしゃ）は、島根県松江市八雲町熊野にある神社。式内社（名神大社）、出雲国一宮。'),
    ('美保神社', null, '島根県', null, 35.5622806, 133.3066667, 'A', '神社仏閣', null),
    ('圓隆寺', null, '広島県', null, 34.389227, 132.4625932, 'A', '神社仏閣', 'とうかさん（稲荷さん・稲荷山・稲荷参）は、広島県広島市中区三川町にある日蓮宗の寺院、福昌山 慈善院 圓隆寺（ふくしょうざん じぜんいん えんりゅうじ）のこと。'),
    ('大聖院', null, '広島県', null, 34.2917429, 132.3185618, 'A', '神社仏閣', '大聖院（だいしょういん）は広島県廿日市市宮島町にある真言宗御室派の大本山の寺院。山号は多喜山（たきざん、「滝山」とも）、多喜山大聖院水精寺（すいしょうじ）と号する。'),
    ('耕三寺', null, '広島県', null, 34.3039622, 133.0898242, 'A', '神社仏閣', null),
    ('大山祇神社', null, '愛媛県', null, 34.2481099, 133.0051084, 'S', '神社仏閣', '大山祇神社（おおやまづみじんじゃ）は、愛媛県今治市大三島町宮浦にある神社。式内社（名神大社）、伊予国一宮。'),
    ('大樹寺', null, '愛知県', null, 34.9843176, 137.1652924, 'A', '神社仏閣', '大樹寺（だいじゅじ / だいじゅうじ）は、愛知県岡崎市鴨田町にある浄土宗の寺院。徳川氏（松平氏）の菩提寺。'),
    ('真清田神社', null, '愛知県', null, 35.3075018, 136.8019814, 'A', '神社仏閣', null),
    ('覚王山日泰寺', null, '愛知県', null, 35.1715764, 136.9550206, 'A', '神社仏閣', null),
    ('豊川稲荷', null, '愛知県', null, 34.8257995, 137.3927463, 'A', '神社仏閣', null),
    ('上野東照宮', null, '東京都', null, 35.7153982, 139.7706324, 'A', '神社仏閣', '上野東照宮（うえのとうしょうぐう）は、東京都台東区上野恩賜公園内にある神社。旧社格は府社。'),
    ('九品仏浄真寺', null, '東京都', null, 35.6084285, 139.6606912, 'A', '神社仏閣', '九品仏浄真寺（くほんぶつじょうしんじ）は、東京都世田谷区奥沢七丁目にある浄土宗の寺である。山号は「九品山」、正式名称は「九品山唯在念佛院淨眞寺」。'),
    ('傳通院', null, '東京都', null, 35.7124809, 139.746878, 'A', '神社仏閣', '伝通院（でんづういん）は、東京都文京区小石川三丁目の高台にある浄土宗の寺。正式名称は、無量山 伝通院 寿経寺（むりょうざん・でんづういん・じゅきょうじ）。'),
    ('回向院', null, '東京都', '墨田区', 35.6933386, 139.7920396, 'A', '神社仏閣', '回向院（えこういん）は、東京都墨田区両国二丁目にある浄土宗の寺院、および過去にその別院であった東京都荒川区南千住五丁目にある寺院。'),
    ('富岡八幡宮', null, '東京都', null, 35.6715882, 139.799754, 'A', '神社仏閣', '富岡八幡宮（とみおかはちまんぐう）は、東京都江東区富岡にある八幡神社。通称で深川八幡宮（ふかがわはちまんぐう）とも称される。'),
    ('寛永寺', null, '東京都', '台東区', 35.7215778, 139.7743693, 'S', '神社仏閣', '寛永寺（かんえいじ）は、東京都台東区上野桜木一丁目にある天台宗関東総本山の寺院。山号は東叡山（とうえいざん）。'),
    ('小網神社', null, '東京都', null, 35.6841674, 139.7804475, 'A', '神社仏閣', '小網神社（こあみじんじゃ）は、東京都中央区日本橋小網町にある神社。「小網神社社殿及び神楽殿附棟札・造営関係資料」は中央区有形文化財となっている（1991年4月1日指定）。'),
    ('小野神社', null, '東京都', null, 35.6530699, 139.4419497, 'A', '神社仏閣', '小野神社（おのじんじゃ）は、東京都多摩市にある神社。式内社論社、武蔵国一宮を称する。'),
    ('愛宕神社', null, '東京都', null, 35.6649257, 139.7488172, 'A', '神社仏閣', '愛宕神社（あたごじんじゃ）は、東京都港区愛宕一丁目にある神社。戦勝や防火に連なる愛宕権現を祀っており（愛宕信仰）、京都の愛宕神社が総本社である。'),
    ('成願寺', null, '東京都', null, 35.6940522, 139.6817876, 'C', '神社仏閣', '成願寺（じょうがんじ）は、東京都中野区本町二丁目にある曹洞宗の寺院。山号は多宝山（たほうざん）。'),
    ('日枝神社', null, '東京都', null, 35.6746457, 139.739932, 'S', '神社仏閣', '日枝神社（ひえじんじゃ）は、東京都千代田区永田町二丁目にある、山王信仰の神社。山王さま等とも呼ばれ、江戸三大祭の一つ、山王祭が行われる。'),
    ('東京大神宮', null, '東京都', null, 35.7000073, 139.7468581, 'A', '神社仏閣', '東京大神宮（とうきょうだいじんぐう）は、東京都千代田区富士見二丁目にある神社。天照皇大神・豊受大神を主祭神とする。'),
    ('松陰神社', null, '東京都', null, 35.6471805, 139.6561244, 'A', '神社仏閣', null),
    ('柴又帝釈天', null, '東京都', '葛飾区', 35.7584204, 139.8787384, 'A', '神社仏閣', '柴又帝釈天（しばまたたいしゃくてん）または、帝釈天 題経寺（たいしゃくてん だいきょうじ）は、東京都葛飾区柴又七丁目にある日蓮宗の寺院。'),
    ('浄閑寺', null, '東京都', null, 35.7307451, 139.7927922, 'A', '神社仏閣', '浄閑寺（じょうかんじ）は東京都荒川区南千住にある浄土宗の寺院。山号は栄法山。'),
    ('深大寺', null, '東京都', null, 35.6674305, 139.5503387, 'S', '神社仏閣', '深大寺（じんだいじ）は、東京都調布市深大寺元町にある仏教寺院。天台宗別格本山で、山号は浮岳山。'),
    ('深川不動尊', null, '東京都', null, 35.6730119, 139.7983051, 'A', '神社仏閣', '成田山 東京別院 深川不動堂（なりたさん とうきょうべついん ふかがわふどうどう）は、東京都江東区富岡にある真言宗智山派の寺院であり、千葉県成田市にある成田山新勝寺の東京別院...'),
    ('湯島天満宮', null, '東京都', '文京区', 35.7076842, 139.7678622, 'A', '神社仏閣', '湯島天満宮（ゆしまてんまんぐう）は、東京都文京区湯島三丁目にある天満宮で、菅原道真を含む二柱の祭神を祀る神社。通称は湯島天神（ゆしまてんじん）、旧称は湯島神社（ゆしまじんじゃ）。'),
    ('目黒不動', null, '東京都', null, 35.6282261, 139.7085663, 'A', '神社仏閣', '瀧泉寺（りゅうせんじ）は、東京都目黒区下目黒に所在する天台宗の寺院。山号は泰叡山（たいえいざん）。'),
    ('真源寺(入谷鬼子母神)', null, '東京都', null, 35.719879, 139.7827173, 'A', '神社仏閣', null),
    ('神田明神', null, '東京都', '千代田区', 35.7019658, 139.7677523, 'S', '神社仏閣', '神田明神（かんだみょうじん）は、東京都千代田区外神田二丁目にある神社。正式名称は神田神社（かんだじんじゃ）。'),
    ('穴守稲荷神社', null, '東京都', null, 35.550272, 139.7494664, 'A', '神社仏閣', '穴守稲荷神社（あなもりいなりじんじゃ）は、東京都大田区羽田にある稲荷神社。祭神は豊受姫命。'),
    ('築地本願寺', null, '東京都', '中央区', 35.6665791, 139.7721306, 'A', '神社仏閣', null),
    ('芝大神宮', null, '東京都', null, 35.657597, 139.7530699, 'A', '神社仏閣', null),
    ('西新井大師', null, '東京都', '足立区', 35.779756, 139.7806452, 'A', '神社仏閣', null),
    ('豪徳寺', null, '東京都', '世田谷区', 35.648682, 139.6473095, 'A', '神社仏閣', null),
    ('青松寺', null, '東京都', null, 35.662854, 139.7484226, 'A', '神社仏閣', null),
    ('高尾山薬王院', null, '東京都', null, 35.6259769, 139.2497267, 'A', '神社仏閣', '高尾山薬王院（たかおさんやくおういん）は、東京都八王子市の高尾山にある寺院。真言宗智山派の関東三大本山の一つ。'),
    ('鳥越神社', null, '東京都', null, 35.7019971, 139.7857711, 'A', '神社仏閣', null),
    ('二荒山神社中宮祠', null, '栃木県', '日光市', 36.7416026, 139.4876546, 'A', '神社仏閣', null),
    ('古峯神社', null, '栃木県', null, 36.6548173, 139.5271523, 'A', '神社仏閣', '古峯神社（ふるみねじんじゃ）は、栃木県鹿沼市草久（くさぎゅう）にある神社。祭神は日本武尊。'),
    ('宇都宮二荒山神社', null, '栃木県', null, 36.5624338, 139.8853744, 'A', '神社仏閣', '宇都宮二荒山神社（うつのみやふたあらやまじんじゃ、-ふたらやまじんじゃ）は、栃木県宇都宮市にある神社。式内社（名神大社）論社、下野国一宮。'),
    ('鑁阿寺', null, '栃木県', null, 36.3375432, 139.4521176, 'A', '神社仏閣', null),
    ('日牟禮八幡宮', null, '滋賀県', null, 35.1409512, 136.0897235, 'A', '神社仏閣', '日牟禮八幡宮（ひむれはちまんぐう）は、滋賀県近江八幡市宮内町にある神社。旧社格は県社で、現在は神社本庁の別表神社。'),
    ('白鬚神社', null, '滋賀県', null, 35.2745838, 136.0110627, 'A', '神社仏閣', null),
    ('石山寺', null, '滋賀県', null, 34.9604102, 135.9054905, 'A', '神社仏閣', '石山寺（いしやまでら）は、滋賀県大津市石山寺にある東寺真言宗の大本山の寺院。山号は石光山。'),
    ('都久夫須麻神社', null, '滋賀県', null, 35.4205104, 136.1442493, 'A', '神社仏閣', null),
    ('伊勢山皇大神宮', null, '神奈川県', null, 35.4503736, 139.6262336, 'A', '神社仏閣', '伊勢山皇大神宮（いせやまこうたいじんぐう）は、神奈川県横浜市西区宮崎町にある神社。'),
    ('寒川神社', null, '神奈川県', '寒川町', 35.3790142, 139.38316, 'A', '神社仏閣', '寒川神社（さむかわじんじゃ）は、神奈川県高座郡寒川町宮山に鎮座する神社。相模國一之宮。'),
    ('大雄山最乗寺', null, '神奈川県', null, 35.3019559, 139.0754344, 'A', '神社仏閣', null),
    ('平塚八幡宮', null, '神奈川県', '平塚市', 35.3336368, 139.3490446, 'A', '神社仏閣', '平塚八幡宮（ひらつかはちまんぐう）は、神奈川県平塚市浅間町（せんげんちょう）にある神社。旧社格は県社で、現在は神社本庁の別表神社。'),
    ('弘明寺', null, '神奈川県', '横浜市', 35.4242245, 139.5975361, 'A', '神社仏閣', '弘明寺（ぐみょうじ）は、神奈川県横浜市南区弘明寺町にある高野山真言宗の寺院。瑞應山蓮華院と号し、横浜市内最古の寺院である。'),
    ('明月院', null, '神奈川県', '鎌倉市', 35.3349178, 139.5516872, 'A', '神社仏閣', '明月院（めいげついん）は、神奈川県鎌倉市山ノ内にある臨済宗建長寺派の寺院。正式には福源山明月院（ふくげんざめいげついん）と号する。'),
    ('松岡山東慶寺', null, '神奈川県', '鎌倉市', 35.3344556, 139.5456041, 'A', '神社仏閣', '東慶寺（とうけいじ）は、神奈川県鎌倉市山ノ内にある臨済宗円覚寺派の寺院である。山号は松岡山、寺号は東慶総持禅寺。'),
    ('極楽寺', null, '神奈川県', '鎌倉市', 35.3101158, 139.5288013, 'A', '神社仏閣', '極楽寺（ごくらくじ）は、神奈川県鎌倉市極楽寺にある真言律宗の寺院である。霊鷲山感応院極楽律寺（りゅうじゅさん かんのういん ごくらくりつじ）と号する。'),
    ('箱根神社', null, '神奈川県', null, 35.2039578, 139.0255666, 'A', '神社仏閣', null),
    ('鎌倉宮', null, '神奈川県', null, 35.3258941, 139.5667848, 'A', '神社仏閣', null),
    ('阿夫利神社本社', null, '神奈川県', '伊勢原市', 35.4406014, 139.2311081, 'A', '神社仏閣', '大山阿夫利神社（おおやまあふりじんじゃ）は、神奈川県伊勢原市の大山（別名: 雨降山〈あふりやま〉）にある神社である。'),
    ('伊佐須美神社', null, '福島県', null, 37.4564105, 139.8404408, 'A', '神社仏閣', '伊佐須美神社（いさすみじんじゃ）は、福島県大沼郡会津美里町宮林にある神社。式内社（名神大社）、陸奥国二宮。'),
    ('鎌原観音堂', null, '群馬県', null, 36.5161836, 138.5484, 'A', '神社仏閣', null),
    ('修多羅寺', null, '茨城県', null, 36.4751657, 140.2850357, 'D', '神社仏閣', '修多羅寺（しゅたらじ）は、茨城県東茨城郡城里町小勝にある日蓮宗の寺院。山号は長久山、旧本山は大本山法華経寺(中山門流)。'),
    ('大杉神社', null, '茨城県', null, 35.9522474, 140.3826995, 'A', '神社仏閣', '大杉神社（おおすぎじんじゃ）は、茨城県稲敷市阿波（あば）にある神社。豪奢な社殿を擁することから「茨城の日光東照宮」の異名がある。'),
    ('大甕神社', null, '茨城県', null, 36.5140348, 140.6128827, 'A', '神社仏閣', '大甕神社（おおみかじんじゃ）は、茨城県日立市大みか町にある神社。'),
    ('生島足島神社', null, '長野県', null, 36.3604632, 138.2180323, 'A', '神社仏閣', null),
    ('穂高神社', null, '長野県', null, 36.3386217, 137.8843104, 'A', '神社仏閣', null),
    ('三嶋大社', null, '静岡県', '三島市', 35.121854, 138.9190723, 'A', '神社仏閣', '三嶋大社（みしまたいしゃ、三島大社）は、静岡県三島市大宮町にある神社。式内社（名神大社）、伊豆国一宮、伊豆国総社。'),
    ('伊豆山神社', null, '静岡県', null, 35.1155083, 139.0824723, 'A', '神社仏閣', '伊豆山神社（いずさんじんじゃ又はいずやまじんじゃ）は、静岡県熱海市伊豆山にある神社。'),
    ('大石寺', null, '静岡県', null, 35.2803961, 138.5844896, 'A', '神社仏閣', '大石寺（たいせきじ）は、日蓮正宗総本山の寺院である。宗祖は日蓮。'),
    ('富士山本宮浅間大社', null, '静岡県', '富士宮市', 35.2273066, 138.6101708, 'S', '神社仏閣', '富士山本宮浅間大社（ふじさんほんぐうせんげんたいしゃ）は、静岡県富士宮市にある神社。式内社（名神大社）、駿河国一宮。'),
    ('秋葉山本宮秋葉神社上社', null, '静岡県', null, 34.9811091, 137.8656319, 'A', '神社仏閣', null),
    ('霧島神宮', null, '鹿児島県', '霧島市', 31.8586127, 130.8712947, 'A', '神社仏閣', null),
    ('鹿児島神宮', null, '鹿児島県', '霧島市', 31.7536248, 130.7380701, 'A', '神社仏閣', '鹿児島神宮（かごしまじんぐう）は、鹿児島県霧島市隼人町内（はやとちょううち）にある神社。式内大社（国幣大社）、大隅国一宮。'),

    -- 上記172件追加時の重複判定に不具合があった(都道府県を無視した名前一致、300m以内なら
    -- 無条件で「既存扱い」)ため見落とされていた47件を追加(川崎大師・総持寺(神奈川)など)。
    -- 判定を「同一都道府県内での名前一致」または「100m以内の近接」に修正し、さらに
    -- 目視で「金龍山浅草寺」「中尊寺(金色堂と同一)」等の実質重複4件を除外している。
    ('三十三間堂', null, '京都府', null, 34.9879926, 135.7717834, 'S', '神社仏閣', '三十三間堂（さんじゅうさんげんどう）は、京都市東山区三十三間堂廻町にある天台宗の寺院。本尊は千手観音。'),
    ('三千院', null, '京都府', null, 35.1195241, 135.8350497, 'A', '神社仏閣', '三千院（さんぜんいん）は、京都市左京区大原来迎院町にある天台宗の寺院。山号は魚山（ぎょざん）。'),
    ('佛光寺', null, '京都府', '下京区', 35.0007264, 135.7622696, 'A', '神社仏閣', '佛光寺（ぶっこうじ）は、京都市下京区高倉通仏光寺下ル新開町にある真宗佛光寺派の本山の寺院。山号は渋谷山（汁谷山）。'),
    ('八坂神社', null, '京都府', null, 35.0034854, 135.778387, 'S', '神社仏閣', '八坂神社（やさかじんじゃ）は、京都府京都市東山区祇園町北側にある神社。二十二社（下八社）の一社。'),
    ('善峯寺', null, '京都府', null, 34.9384086, 135.64429, 'A', '神社仏閣', '善峯寺（よしみねでら）は、京都市西京区にある善峰観音宗の本山の寺院。山号は西山。'),
    ('大雲院', null, '京都府', null, 35.0021092, 135.7800589, 'A', '神社仏閣', '大雲院（だいうんいん）は、京都市東山区祇園町にある浄土宗系単立の寺院。山号は龍池山。'),
    ('天龍寺', null, '京都府', null, 35.0161665, 135.6746179, 'S', '神社仏閣', '天龍寺（てんりゅうじ）は、京都市右京区嵯峨天龍寺芒ノ馬場町にある臨済宗天龍寺派の大本山の寺院。山号は霊亀山（れいぎざん）。'),
    ('宇治上神社', null, '京都府', null, 34.8920436, 135.8114973, 'A', '神社仏閣', '宇治上神社（うじがみじんじゃ/うじかみじんじゃ）は、京都府宇治市宇治山田にある神社。式内社で、旧社格は村社。'),
    ('建仁寺', null, '京都府', null, 35.0001782, 135.7746022, 'A', '神社仏閣', '建仁寺（けんにんじ）は、京都市東山区にある臨済宗建仁寺派の大本山の寺院。山号は東山（とうざん）。'),
    ('東本願寺', null, '京都府', null, 34.9913887, 135.7583906, 'S', '神社仏閣', '東本願寺（ひがしほんがんじ）は、京都市下京区にある真宗大谷派の本山の寺院。山号はなし。'),
    ('清凉寺', null, '京都府', null, 35.0235725, 135.6744762, 'A', '神社仏閣', '清凉寺（せいりょうじ）は、京都市右京区嵯峨釈迦堂藤ノ木町にある浄土宗の寺院。山号は五台山（ごだいさん）。'),
    ('西本願寺', null, '京都府', null, 34.991585, 135.7510539, 'S', '神社仏閣', null),
    ('金戒光明寺', null, '京都府', null, 35.0194721, 135.7884216, 'A', '神社仏閣', null),
    ('高台寺', null, '京都府', null, 35.0003229, 135.781354, 'A', '神社仏閣', null),
    ('高山寺', null, '京都府', null, 35.0604829, 135.6777774, 'A', '神社仏閣', '高山寺（こうざんじ、こうさんじ）は、京都市右京区梅ヶ畑栂尾町（とがのおちょう）にある真言宗系単立の寺院。山号は栂尾山。'),
    ('龍光院', null, '京都府', null, 35.0421148, 135.7434513, 'A', '神社仏閣', null),
    ('龍安寺', null, '京都府', null, 35.0334933, 135.7180571, 'S', '神社仏閣', null),
    ('一乗寺', null, '兵庫県', null, 34.8593676, 134.818857, 'A', '神社仏閣', '一乗寺（いちじょうじ）は、兵庫県加西市にある天台宗の寺院。山号は法華山。'),
    ('多田神社', null, '兵庫県', null, 34.8608963, 135.402667, 'A', '神社仏閣', '多田神社（ただじんじゃ）は、兵庫県川西市多田院多田所町にある神社。旧社格は県社で、現在は神社本庁の別表神社。'),
    ('廣田神社', null, '兵庫県', null, 34.7529338, 135.3400056, 'A', '神社仏閣', '廣田神社（ひろたじんじゃ、広田神社）は、兵庫県西宮市大社町にある神社。式内社（名神大社）、二十二社（下八社）の一社。'),
    ('生田神社', null, '兵庫県', null, 34.6947669, 135.1904861, 'A', '神社仏閣', '生田神社（いくたじんじゃ）は、兵庫県神戸市中央区にある神社。式内社（名神大社）で、旧社格は官幣中社。'),
    ('西宮神社', null, '兵庫県', '西宮市', 34.7352092, 135.3346532, 'A', '神社仏閣', null),
