    ('大安寺', null, '奈良県', null, 34.6679364, 135.8127455, 'A', '神社仏閣', '大安寺（だいあんじ）は、奈良県奈良市大安寺二丁目にある高野山真言宗の寺院。山号はなし。'),
    ('橘寺', null, '奈良県', null, 34.469922, 135.8179167, 'A', '神社仏閣', '橘寺（たちばなでら）は、奈良県高市郡明日香村橘にある天台宗の寺院。山号は仏頭山。'),
    ('薬師寺', null, '奈良県', '奈良市', 34.6687298, 135.7845238, 'S', '神社仏閣', null),
    ('飛鳥寺', null, '奈良県', '明日香村', 34.478654, 135.8201676, 'S', '神社仏閣', null),
    ('鳥海山大物忌神社', null, '山形県', null, 39.0977038, 140.048707, 'A', '神社仏閣', null),
    ('乃木神社', null, '東京都', '港区', 35.668586, 139.727995, 'A', '神社仏閣', '乃木神社（のぎじんじゃ）は、東京都港区赤坂にある神社。明治期の軍人・乃木希典（乃木希典命）とその妻・乃木静子（乃木静子命）を祀る。'),
    ('吉祥寺', null, '東京都', '文京区', 35.7278356, 139.7545071, 'C', '神社仏閣', '吉祥寺（きちじょうじ）は、東京都文京区本駒込三丁目にある曹洞宗の寺院。山号は諏訪山。'),
    ('根津神社', null, '東京都', '文京区', 35.7200041, 139.7607627, 'A', '神社仏閣', '根津神社（ねづじんじゃ）は、東京都文京区根津にある神社。旧社格は府社で、元准勅祭社（東京十社）。'),
    ('白山神社', null, '東京都', null, 35.7218967, 139.7505773, 'A', '神社仏閣', '白山神社（はくさんじんじゃ）は、東京都文京区白山にある神社である。旧称白山権現社。'),
