    ('二荒山神社', null, '栃木県', '日光市', 36.7583924, 139.5963813, 'S', '神社仏閣', '日光二荒山神社（にっこうふたらさんじんじゃ）は、栃木県日光市にある神社。式内社（名神大社）論社、下野国一宮。'),
    ('瑞龍寺', null, '滋賀県', null, 35.1442784, 136.0824889, 'A', '神社仏閣', '瑞龍寺（ずいりゅうじ）は、滋賀県近江八幡市宮内町にある日蓮宗の本山（由緒寺院）。山号はなく御所号「村雲御所」を冠する。'),
    ('阿蘇神社', null, '熊本県', '阿蘇市', 32.9476916, 131.1160299, 'A', '神社仏閣', null),
    ('円光寺', null, '神奈川県', null, 35.4189174, 139.3465422, 'D', '神社仏閣', '円光寺（えんこうじ）は神奈川県厚木市愛甲にある臨済宗建長寺派の寺院。山号は西嶺山で「円光禅寺」とも称す。'),
    ('川崎大師', null, '神奈川県', '川崎市', 35.5340918, 139.7294498, 'A', '神社仏閣', '平間寺（へいけんじ）は、神奈川県川崎市川崎区にある、真言宗智山派の大本山。1128年（大治3年）建立。'),
    ('清浄光寺', null, '神奈川県', null, 35.3480792, 139.4883602, 'A', '神社仏閣', '清浄光寺（しょうじょうこうじ）は、神奈川県藤沢市にある時宗総本山の寺院。藤沢山無量光院清浄光寺と号す。'),
    ('称名寺', null, '神奈川県', null, 35.3436312, 139.6300425, 'A', '神社仏閣', '称名寺（しょうみょうじ）は、神奈川県横浜市金沢区金沢町にある真言律宗別格本山の寺院。山号は金沢山（きんたくさん）。'),
    ('総持寺', null, '神奈川県', null, 35.5068191, 139.6708526, 'S', '神社仏閣', null),
